<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, Bell, BriefcaseBusiness, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleDollarSign, ClipboardCheck, Clock3, Database, FileCheck2, FileText, FolderClosed, LayoutDashboard, ListFilter, LoaderCircle, LogOut, Plus, Scale, Search, Settings2, ShieldCheck, Sparkles, Stamp, Users, X, Pencil, Upload, Trash2, History, LockKeyhole, AlertCircle, Building2, MoreHorizontal } from 'lucide-vue-next'
import { api, post, patch, currency, dateFull, dateText } from './api'
import StatusBadge from './components/StatusBadge.vue'
import SchemaForm from './components/SchemaForm.vue'
import RecordTable from './components/RecordTable.vue'
import AuthRecovery from './components/AuthRecovery.vue'
import PasswordResetAdmin from './components/PasswordResetAdmin.vue'
import HistoricalSnapshot from './components/HistoricalSnapshot.vue'
import AdminDepartments from './components/AdminDepartments.vue'
import AdminMetadata from './components/AdminMetadata.vue'
import AdminApiKeys from './components/AdminApiKeys.vue'
import LawyerTeam from './components/LawyerTeam.vue'
import PersonPicker from './components/PersonPicker.vue'
const recoveryMode=ref(false)

const user = ref<any>(null), setupRequired = ref(false), booting = ref(true), busy = ref(false), loading = ref(false)
const auth = reactive({ username: 'admin', password: '', name: '管理员', demo: true })
const authError = ref(''), schemas = ref<any>({}), states = ref<any>({}), transitions = ref<any>({}), roles = ref<any>({})
const lawyers = ref<any[]>([]), settings = ref<any>({ firm: { name: '律序律师事务所', subtitle: '专业有序 · 协作有方' } })
const dashboard = ref<any>({ stats: {}, funds: {}, categories: {}, tasks: [], pending: [], activity: [] })
const nav = [
  { key: 'dashboard', label: '工作总览', icon: LayoutDashboard }, { key: 'cases', label: '案件管理', icon: BriefcaseBusiness },
  { key: 'conflicts', label: '利益冲突', icon: ShieldCheck }, { key: 'finance', label: '财务管理', icon: CircleDollarSign },
  { key: 'documents', label: '案件文档', icon: FolderClosed }, { key: 'seals', label: '用印管理', icon: Stamp },
  { key: 'tasks', label: '日程与待办', icon: CalendarDays }, { key: 'lawyers', label: '律师团队', icon: Users },
]
const page = ref('dashboard'), selectedCase = ref<any>(null), caseTab = ref('overview'), financeTab = ref('invoices')
const caseTabs = [ ['overview', 'Overview 总览'], ['intake', '立案流程'], ['contracts', '合同盖章 / 归档'], ['finance', '财务信息'], ['documents', '案件文档'], ['seals', '案件用印'], ['parties', '当事人'], ['tasks', '日程与任务'], ['legacy', '源数据 / 历史'] ]
const records = ref<any[]>([]), total = ref(0), listPage = ref(1), pageSize = 10, search = ref(''), filterStatus = ref(''), caseBranch = ref('')
const caseLists = ref<Record<string, any[]>>({}), caseTotals = ref<Record<string, number>>({}), casePages = reactive<Record<string, number>>({})
const currentKind = computed(() => page.value === 'finance' ? financeTab.value === 'allocations' ? 'invoices' : financeTab.value : page.value)
const currentTitle = computed(() => page.value === 'admin' ? '管理后台' : nav.find(x => x.key === page.value)?.label || '工作总览')
const pageSubtitle: Record<string,string> = { cases: '以案件为中心，连接业务流程与团队协作', conflicts: '在承接之前审慎核查，让每一份委托更有保障', finance: '从申请开票到确认到账，每笔收入清晰可溯', documents: '汇集案件材料，保留每一次文档更新', seals: '用印申请、审批与归档，全流程有据可查', tasks: '掌握案件节点，让重要期限不再错过', lawyers: '专业同行，高效协作' }
const toast = ref<{ message: string; error: boolean } | null>(null)
let toastTimer: ReturnType<typeof setTimeout>, searchTimer: ReturnType<typeof setTimeout>
function notify(message: string, error = false) { toast.value = { message, error }; clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.value = null, error ? 8000 : 4000) }
async function run(action: () => Promise<any>) { if (busy.value) return; busy.value = true; try { return await action() } catch (e: any) { notify(e.message, true) } finally { busy.value = false } }
function stateLabel(kind: string, status: string) { return states.value[kind]?.[status] || status || '未设置' }
function lawyerName(id: string) { return lawyers.value.find(x => x.id === id)?.name || '未指派' }
const todayText = new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' }).format(new Date())
const fund = computed(() => dashboard.value.funds.CNY || { contract: 0, received: 0, invoiced: 0 })
const latestConflict = computed(() => caseLists.value.conflicts?.[0])
const conflictApproved = computed(() => latestConflict.value && ['cleared','waived'].includes(latestConflict.value.status) && latestConflict.value.fingerprint === selectedCase.value?.conflict_fingerprint)
const intakeStage = computed(() => {
  if (!selectedCase.value) return 0
  if (['active','closed','archived'].includes(selectedCase.value.status)) return 4
  if (selectedCase.value.status === 'submitted') return 3
  if (conflictApproved.value) return 2
  return latestConflict.value ? 1 : 0
})
const visibleCaseKind = computed(() => caseTab.value === 'finance' ? financeTab.value : caseTab.value)
const formReferences = ref<Record<string,any[]>>({})
const references = computed(() => ({ documents: formReferences.value.documents || caseLists.value.documents || [], invoices: formReferences.value.invoices || caseLists.value.invoices || [], payment_plans: formReferences.value.payment_plans || caseLists.value.payment_plans || [] }))
const allowedAdmin = computed(() => ['admin','partner'].includes(user.value?.role))

async function loadLawyers() {
  let next = 1, items: any[] = [], count = 1
  while (items.length < count) { const result = await api(`/records/lawyers?page=${next++}&page_size=200`); items.push(...result.items); count = result.total; if (!result.items.length) break }
  lawyers.value = items
}
async function initialize() {
  const [schema, cfg] = await Promise.all([api('/schema'), api('/settings')])
  schemas.value = schema.schemas; states.value = schema.states; transitions.value = schema.transitions; roles.value = schema.roles; settings.value = cfg
  await loadLawyers(); await navigateFromHash()
}
async function signIn() {
  authError.value = ''; busy.value = true
  try {
    if (setupRequired.value) { await post('/setup', auth); setupRequired.value = false }
    user.value = await post('/auth/login', auth); auth.password = ''; await initialize()
  } catch (e: any) { authError.value = e.message } finally { busy.value = false }
}
async function signOut() { await post('/auth/logout', {}); user.value = null; selectedCase.value = null; window.location.hash = 'dashboard' }
function navigate(key: string) { window.location.hash = key; if (page.value === key && !selectedCase.value) refresh() }
function navigateCase(caseId: string, tab = 'overview') { caseTab.value = tab; window.location.hash = `cases/${caseId}`; if (selectedCase.value?.id === caseId) refreshCase() }
async function navigateFromHash() {
  if (!user.value) return
  const [key, id] = window.location.hash.replace(/^#/, '').split('/')
  page.value = [...nav.map(x => x.key), 'admin'].includes(key) ? key : 'dashboard'
  selectedCase.value = null; search.value = ''; filterStatus.value = ''; caseBranch.value = ''; listPage.value = 1
  if (page.value === 'cases' && id) { await loadCase(id); return }
  await refresh()
}
let requestSeq = 0
async function loadList() {
  const seq = ++requestSeq
  loading.value = true
  try {
    const branch = currentKind.value === 'cases' ? '&branch=' + encodeURIComponent(caseBranch.value) : ''
    const result = await api(`/records/${currentKind.value}?page=${listPage.value}&page_size=${pageSize}&q=${encodeURIComponent(search.value)}&status=${encodeURIComponent(filterStatus.value)}${branch}`)
    if (seq === requestSeq) { records.value = result.items; total.value = result.total }
  } finally { if (seq === requestSeq) loading.value = false }
}
async function loadCase(id: string) {
  if(selectedCase.value?.id!==id)Object.keys(casePages).forEach(key=>delete casePages[key])
  loading.value = true
  try { selectedCase.value = await api(`/records/cases/${id}`); await loadCaseChildren() } catch(e: any) { notify(e.message,true); navigate('cases') } finally { loading.value = false }
}
async function loadCaseChildren() {
  const id = selectedCase.value?.id; if (!id) return
  const kinds = ['conflicts','contracts','invoices','receipts','payment_plans','allocations','documents','seals','parties','tasks']
  const results = await Promise.all(kinds.map(kind => api(`/records/${kind}?case_id=${id}&page_size=200&page=${casePages[kind] || 1}`).then(r => [kind,r])))
  for (const [kind,result] of results) { caseLists.value[kind] = result.items; caseTotals.value[kind] = result.total }
}
async function refreshCase() { if (selectedCase.value) await loadCase(selectedCase.value.id) }
async function refresh() {
  try {
    if (selectedCase.value) await refreshCase()
    else if (page.value === 'dashboard') { dashboard.value = await api('/dashboard'); const r = await api('/records/cases?page_size=5'); records.value = r.items }
    else if (page.value === 'admin') await loadAdmin()
    else await loadList()
  } catch(e: any) { notify(e.message,true) }
}
watch([search, filterStatus, caseBranch], () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => { listPage.value = 1; if (user.value && !selectedCase.value && page.value !== 'dashboard' && page.value !== 'admin') loadList().catch(e=>notify(e.message,true)) }, 280) })
watch(listPage, () => { if (!selectedCase.value && user.value) loadList().catch(e=>notify(e.message,true)) })
watch(financeTab, () => { if (page.value === 'finance' && !selectedCase.value) { listPage.value = 1; filterStatus.value = ''; loadList().catch(e=>notify(e.message,true)) } })

const modal = ref(''), modalKind = ref(''), form = reactive<Record<string,any>>({}), editId = ref(''), formVersion = ref(0), formCase = ref('')
const formCaseChoices = ref<any[]>([]), modalTitle = ref(''), inspector = ref<any>(null), historyRows = ref<any[]>([])
const formFields = computed(() => modal.value === 'intake' ? schemas.value.cases?.fields.filter((f: any) => ['title','office','client','opponent','lead_lawyer_id','description'].includes(f.key)) : schemas.value[modalKind.value]?.fields || [])
function resetForm() { formReferences.value={}; Object.keys(form).forEach(k=>delete form[k]); editId.value = ''; formVersion.value = 0; formCase.value = selectedCase.value?.id || '' }
async function openForm(kind: string, record?: any) {
  if (kind === 'conflicts') { if (selectedCase.value) { modal.value = 'conflict'; Object.assign(conflictForm,{ query:'',notes:'' }) } else openIntake(); return }
  if (kind === 'documents' && !record) { await openUpload(); return }
  if (kind === 'cases' && !record) { openIntake(); return }
  resetForm(); modalKind.value = kind
  const current = record ? await api(`/records/${kind}/${record.id}`) : null
  for (const field of schemas.value[kind].fields) form[field.key] = current?.[field.key] ?? field.default ?? (field.type === 'boolean' ? false : '')
  if (current) { editId.value = current.id; formVersion.value = current.version; formCase.value = current.case_id || '' }
  if (kind !== 'cases' && kind !== 'lawyers' && !selectedCase.value) { formCaseChoices.value = (await api('/records/cases?page_size=200&status=active')).items; if (formCase.value) await loadFormReferences(formCase.value) }
  if (selectedCase.value && !['cases','lawyers'].includes(kind)) await loadFormReferences(selectedCase.value.id)
  modalTitle.value = `${current ? '编辑' : '新增'}${schemas.value[kind].label}`; modal.value = 'form'
}
function openIntake() {
  if (!lawyers.value.some(x=>x.status === 'active')) { notify('请先在律师团队中新增主办律师'); navigate('lawyers'); return }
  resetForm(); modalKind.value = 'cases'
  for (const field of schemas.value.cases.fields) form[field.key] = field.default ?? (field.type === 'boolean' ? false : '')
  Object.assign(form,{ number: `LX-${new Date().getFullYear()}-${Date.now().toString().slice(-7)}`, opened_on: new Date().toLocaleDateString('sv-SE'), lead_lawyer_id: user.value.lawyer_id || lawyers.value.find(x=>x.status === 'active')?.id })
  modalTitle.value = '发起立案 · 创建利冲'; modal.value = 'intake'
}
async function loadFormReferences(caseId: string) {
  for (const kind of ['documents','invoices','payment_plans']) { let next=1,items:any[]=[],count=1;while(items.length<count){const r=await api(`/records/${kind}?case_id=${caseId}&page_size=200&page=${next++}`);items.push(...r.items);count=r.total;if(!r.items.length)break};formReferences.value[kind]=items }
}
async function searchCaseChoices(event:Event) { const q=(event.target as HTMLInputElement).value; formCaseChoices.value=(await api(`/records/cases?page_size=100&q=${encodeURIComponent(q)}`)).items }
async function saveForm() {
  await run(async () => {
    const body: any = { ...form }; if (formCase.value) body.case_id = formCase.value
    if (editId.value) body.version = formVersion.value
    const result = editId.value ? await patch(`/records/${modalKind.value}/${editId.value}`, body) : await post(`/records/${modalKind.value}`, body)
    const isIntake = modal.value === 'intake'; modal.value = ''; inspector.value = null
    if (modalKind.value === 'lawyers') await loadLawyers()
    if (isIntake) { await post(`/cases/${result.id}/conflicts`, {}); navigateCase(result.id, 'intake'); notify('利冲已创建，等待合伙人审批') }
    else { notify('保存成功'); await refresh() }
  })
}
async function openRecord(record: any) {
  if (record.kind === 'cases' || currentKind.value === 'cases' && !record.kind) { navigateCase(record.id); return }
  inspector.value = await api(`/records/${record.kind}/${record.id}`); historyRows.value = []
}
async function showHistory(record: any) { historyRows.value = await api(`/history/${record.id}`) }
const actionRecord = ref<any>(null), actionTarget = ref(''), actionNote = ref('')
const actionNames: Record<string,string> = { draft:'填写立案申请', submitted:'提交审批', active:'审批通过 / 正式立案', rejected:'退回修改', approved:'审批通过', issued:'确认开票', confirmed:'确认到账', stamped:'完成盖章', collected:'确认领取', archived:'完成归档', closed:'申请结案', void:'撤销 / 作废', cleared:'无冲突通过', waived:'豁免通过', blocked:'禁止承接', stamping:'申请合同盖章', done:'标记完成', open:'重新打开', inactive:'设为离职' }
function canWrite(kind:string) { return (({cases:['admin','partner','lawyer'],lawyers:['admin'],parties:['admin','partner','lawyer'],allocations:['admin','partner','finance'],invoices:['admin','partner','lawyer','finance'],receipts:['admin','finance'],payment_plans:['admin','partner','finance'],documents:['admin','partner','lawyer','clerk'],contracts:['admin','partner','lawyer','clerk'],seals:['admin','partner','lawyer','clerk'],tasks:['admin','partner','lawyer','clerk'],conflicts:['admin','partner','lawyer']} as Record<string,string[]>)[kind]||[]).includes(user.value?.role) }
function canEdit(record:any) { const locked:Record<string,string[]>={cases:['submitted','archived','void'],invoices:['submitted','issued','void'],receipts:['confirmed','void'],seals:['submitted','collected','void'],contracts:['archived']};return canWrite(record.kind) && !['conflicts','allocations'].includes(record.kind) && !(locked[record.kind]||[]).includes(record.status) }
function canDelete(record:any) { return canWrite(record.kind) && !record.source_key && !['cases','conflicts','lawyers','allocations'].includes(record.kind) && ['draft','open','active','missing'].includes(record.status) }
function actions(record: any) {
  if (!canWrite(record.kind)) return []
  const all: string[] = transitions.value[record.kind]?.[record.status] || []
  const role = user.value?.role
  return all.filter((target: string) => {
    if (record.kind === 'cases' && ['active','rejected','archived','void'].includes(target)) return ['admin','partner'].includes(role)
    if (record.kind === 'conflicts') return ['admin','partner'].includes(role)
    if (record.kind === 'invoices' && ['approved','rejected','issued','void'].includes(target)) return ['admin','finance'].includes(role)
    if (record.kind === 'receipts') return ['admin','finance'].includes(role)
    if (record.kind === 'seals' && ['approved','rejected'].includes(target)) return ['admin','partner'].includes(role)
    if (record.kind === 'seals' && ['stamped','collected'].includes(target)) return ['admin','clerk'].includes(role)
    if (record.kind === 'lawyers') return role === 'admin'
    return true
  })
}
function openAction(record: any, target: string) { actionRecord.value = record; actionTarget.value = target; actionNote.value = ''; modal.value = 'action' }
async function confirmAction() {
  await run(async()=>{ const result = await post(`/records/${actionRecord.value.kind}/${actionRecord.value.id}/transition`,{ status:actionTarget.value,note:actionNote.value,version:actionRecord.value.version }); modal.value=''; if(inspector.value?.id===result.id) inspector.value=result; notify('流程已更新'); await refresh() })
}
function startDelete(record:any) { actionRecord.value=record; modal.value='delete' }
async function confirmDelete() { await run(async()=>{ const r=actionRecord.value; await api(`/records/${r.kind}/${r.id}?version=${r.version}`,{method:'DELETE'}); modal.value='';inspector.value=null;notify('记录已移除，历史已保留');await refresh() }) }
const conflictForm = reactive({ query:'',notes:'' })
async function submitConflict() { await run(async()=>{ await post(`/cases/${selectedCase.value.id}/conflicts`,conflictForm);modal.value='';notify('利冲检索已完成，等待审批');await refreshCase() }) }
const allocationRows = ref<any[]>([]), allocationScope = ref<any>(null)
const allocationTotal = computed(()=>allocationRows.value.reduce((sum,r)=>sum+Number(r.ratio||0),0))
async function openAllocations(scope?:any) {
  allocationScope.value = scope || selectedCase.value
  const all = (await api(`/records/allocations?case_id=${allocationScope.value.kind==='cases'?allocationScope.value.id:allocationScope.value.case_id}&page_size=200`)).items
  allocationRows.value = all.filter((r:any)=>r.scope_id===allocationScope.value.id).map((r:any)=>({lawyer_id:r.lawyer_id,ratio:r.ratio,role:r.role}))
  if (!allocationRows.value.length) allocationRows.value=[{lawyer_id:selectedCase.value?.lead_lawyer_id || '',ratio:'100',role:'主办律师'}]
  modal.value='allocations'
}
async function saveAllocations() { await run(async()=>{ const s=allocationScope.value; const r=await api(`/cases/${s.kind==='cases'?s.id:s.case_id}/allocations`,{method:'PUT',body:JSON.stringify({scope_id:s.id,version:s.version,rows:allocationRows.value})}); if(inspector.value?.id===s.id)inspector.value.version=r.version;modal.value='';notify('分配方案已保存');await refresh() }) }
const uploadFile = ref<File|null>(null), uploadForm = reactive({ title:'',category:'委托合同',case_id:'',document_id:'',version:0 })
async function openUpload(record?:any) {
  uploadFile.value=null;Object.assign(uploadForm,{title:record?.title||'',category:record?.category||'委托合同',case_id:record?.case_id||selectedCase.value?.id||'',document_id:record?.id||'',version:record?.version||0})
  if(!selectedCase.value)formCaseChoices.value=(await api('/records/cases?page_size=200')).items
  modal.value='upload'
}
function filePicked(event: Event) { uploadFile.value=(event.target as HTMLInputElement).files?.[0]||null }
async function doUpload() { await run(async()=>{ if(!uploadFile.value)throw new Error('请选择文件');const body=new FormData();for(const [k,v]of Object.entries(uploadForm))body.append(k,String(v));body.append('file',uploadFile.value);await api('/documents/upload',{method:'POST',body});modal.value='';inspector.value=null;notify('文档上传成功');await refresh() }) }
function downloadFile(record:any,index=-1) { window.open(`/api/documents/${record.id}/download?file_version=${index}`,'_blank','noopener') }
function exportRecords(kind?:string) { const k=kind||currentKind.value;const params=new URLSearchParams({q:search.value,status:filterStatus.value});if(k==='cases'&&!selectedCase.value)params.set('branch',caseBranch.value);if(selectedCase.value)params.set('case_id',selectedCase.value.id);window.location.href=`/api/export/${k}?${params}` }
function displayValue(field:any,record:any) { const value=record[field.key];if(field.type==='lawyer')return lawyerName(value);if(field.type==='money')return currency(value,selectedCase.value?.currency);if(field.type==='boolean')return value?'是':'否';if(['document','invoice','plan'].includes(field.type)){const kind=({document:'documents',invoice:'invoices',plan:'payment_plans'}as any)[field.type];return references.value[kind as keyof typeof references.value]?.find((r:any)=>r.id===value)?.title||value||'—'}return value||'—' }

const migrationIssues=ref<any>({items:[],total:0,summary:[]}),issuePage=ref(1)
const adminTab=ref('users'),adminUsers=ref<any[]>([]),auditRows=ref<any[]>([]),auditTotal=ref(0),auditPage=ref(1),migration=ref<any>({runs:[],tables:[]}),migrationPlan=ref<any>(null)
const adminPeople = computed(() => adminUsers.value.map(account => ({ ...(lawyers.value.find(person => person.id === account.lawyer_id) || {}), ...account })))
const userForm=reactive<any>({username:'',name:'',password:'',role:'lawyer',lawyer_id:''}),userEditId=ref('')
const legacyRecordId=ref(''),legacyTables=ref<string[]>([])
const sourceTable=ref(''),sourceRows=ref<any[]>([]),sourceTotal=ref(0),sourcePage=ref(1)
const passwordForm=reactive({old_password:'',password:''})
async function loadAdmin() {
  if(!allowedAdmin.value){navigate('dashboard');return}
  const auditResult=await api(`/admin/audit?page=${auditPage.value}`);auditRows.value=auditResult.items;auditTotal.value=auditResult.total
  if(user.value.role==='admin') { const [members,migrations,plan,issues]=await Promise.all([api('/admin/users'),api('/admin/migrations'),api('/admin/migration-plan'),api(`/admin/migration-issues?page=${issuePage.value}`)]);adminUsers.value=members;migration.value=migrations;migrationPlan.value=plan;migrationIssues.value=issues }
}
function openUser(record?:any) { userEditId.value=record?.id||'';Object.assign(userForm,{username:record?.username||'',name:record?.name||'',password:'',role:record?.role||'lawyer',lawyer_id:record?.lawyer_id||'',active:record?.active!==0});modal.value='user' }
async function saveUser() { await run(async()=>{if(userEditId.value)await patch(`/admin/users/${userEditId.value}`,userForm);else await post('/admin/users',userForm);modal.value='';notify('账号已保存');await loadAdmin()}) }
async function saveSettings() { await run(async()=>{await api('/admin/settings',{method:'PUT',body:JSON.stringify(settings.value)});notify('律所设置已保存')}) }
async function refreshManagedReferences() {
  try {
    const schema=await api('/schema'); schemas.value=schema.schemas;states.value=schema.states
    await loadLawyers();await loadAdmin();notify('管理信息已保存')
  } catch(e:any){notify(e.message,true)}
}
async function openSource(table:string,p=1) { sourceTable.value=table;sourcePage.value=p;const r=await api(legacyRecordId.value?`/legacy/${legacyRecordId.value}?table=${table}&page=${p}`:`/admin/source/${table}?page=${p}`);sourceRows.value=r.items;sourceTotal.value=r.total;modal.value='source' }
async function openLegacy(record:any) { legacyRecordId.value=record.id; const r=await api(`/legacy/${record.id}`); legacyTables.value=r.tables; if(!r.tables.length){ notify('此记录没有已迁移的关联明细');return }; await openSource(r.tables[0]) }
async function changePassword() { await run(async()=>{await post('/auth/password',passwordForm);modal.value='';await signOut();notify('密码已更新，请重新登录')}) }
async function seedDemo() { await run(async()=>{await post('/admin/demo',{});await loadLawyers();notify('演示数据已载入，与源数据库无关');await refresh()}) }
function handleHash() { navigateFromHash().catch(e=>notify(e.message,true)) }
onMounted(async()=>{
  window.addEventListener('hashchange',handleHash)
  try{const boot=await api('/bootstrap');setupRequired.value=boot.setup_required;if(!boot.setup_required){try{user.value=await api('/auth/me')}catch{user.value=null}if(user.value)await initialize()}}
  catch(e:any){authError.value='后端连接失败：'+e.message}finally{booting.value=false}
})
onUnmounted(()=>{window.removeEventListener('hashchange',handleHash);clearTimeout(toastTimer);clearTimeout(searchTimer)})
</script>

