      <div class="sidebar-bottom"><div class="workspace-note"><div class="icon-tile small"><Sparkles :size="18"/></div><strong>有序工作，从容执业</strong><p>每一个案件，都值得专注。</p></div><button v-if="allowedAdmin" aria-label="管理后台" class="nav-item" :class="{active:page==='admin'}" @click="navigate('admin')"><Settings2 :size="19"/><span>管理后台</span><span class="admin-tag">ADMIN</span></button><button class="profile-button" @click="modal='profile'"><span class="avatar">{{ user.name.slice(-2) }}</span><div><strong>{{ user.name }}</strong><small>{{ roles[user.role] }}</small></div><MoreHorizontal :size="18"/></button></div>
    </aside>
