          <div class="detail-tabs"><button v-for="[key,label] in caseTabs" :key="key" :aria-label="label" :class="{active:caseTab===key}" @click="caseTab=key">{{ label }}<span v-if="caseTotals[key]">{{ caseTotals[key] }}</span></button></div>
          <template v-if="caseTab==='overview'">
            <div class="case-overview-grid"><section class="panel"><div class="panel-heading"><h2>案件概况</h2><span class="pill">{{ selectedCase.stage||'收案' }}</span></div><div class="info-grid"><div><label>委托人</label><strong>{{ selectedCase.client }}</strong></div><div><label>对方当事人</label><strong>{{ selectedCase.opponent||'—' }}</strong></div><div><label>主办律师</label><span class="person"><span class="avatar tiny">{{ lawyerName(selectedCase.lead_lawyer_id).slice(-2) }}</span>{{ lawyerName(selectedCase.lead_lawyer_id) }}</span></div><div><label>业务部门</label><strong>{{ selectedCase.department||'—' }}</strong></div><div><label>案由</label><strong>{{ selectedCase.cause||'待补充' }}</strong></div><div><label>承办法院</label><strong>{{ selectedCase.court||'待补充' }}</strong></div></div><div class="case-description"><label>案情简介</label><p>{{ selectedCase.description||'暂无案情简介，可在立案申请单中补充。' }}</p></div></section><section class="panel finance-overview"><div class="panel-heading"><h2>案件财务</h2><span class="muted">{{ selectedCase.currency }}</span></div><div class="contract-value"><label>合同服务费</label><strong>{{ currency(selectedCase.amount,selectedCase.currency) }}</strong></div><div class="finance-rows"><div><span><i class="legend green"></i>已确认到账</span><strong>{{ currency(selectedCase.finance.received,selectedCase.currency) }}</strong></div><div><span><i class="legend purple"></i>已开票金额</span><strong>{{ currency(selectedCase.finance.invoiced,selectedCase.currency) }}</strong></div><div><span><i class="legend amber"></i>待收款金额</span><strong>{{ currency(selectedCase.finance.outstanding,selectedCase.currency) }}</strong></div></div><button class="text-button" @click="caseTab='finance'">查看财务明细<ArrowRight :size="15"/></button></section></div>
            <section class="panel flow-panel"><div class="panel-heading"><div><h2>案件业务流程</h2><p>三条流程独立流转，关键节点始终可见</p></div><span class="icon-tile lavender small"><Activity :size="18"/></span></div><div class="flow-row"><div class="flow-label"><ShieldCheck :size="20"/><strong>立案流程</strong></div><div class="stepper"><div v-for="(step,i) in ['利冲创建','利冲审批','立案申请单','立案审批']" :key="step" class="flow-step" :class="{done:intakeStage>i,current:intakeStage===i}"><span><Check v-if="intakeStage>i" :size="13"/><template v-else>{{ i+1 }}</template></span><strong>{{ step }}</strong><i v-if="i<3"></i></div></div><button class="text-button" @click="caseTab='intake'">查看流程<ChevronRight :size="15"/></button></div><div class="flow-row"><div class="flow-label"><FileCheck2 :size="20"/><strong>合同流程</strong></div><div class="flow-summary"><span>合同盖章</span><ArrowRight :size="16"/><span>合同归档</span><small>{{ caseLists.contracts?.length||0 }} 份合同 · {{ caseLists.contracts?.filter(c=>c.status==='archived').length||0 }} 份已归档</small></div><button class="text-button" @click="caseTab='contracts'">合同明细<ChevronRight :size="15"/></button></div><div class="flow-row"><div class="flow-label"><CircleDollarSign :size="20"/><strong>财务流程</strong></div><div class="flow-summary"><span>开票申请</span><ArrowRight :size="16"/><span>开票审批</span><ArrowRight :size="16"/><span>到账信息</span></div><button class="text-button" @click="caseTab='finance'">财务明细<ChevronRight :size="15"/></button></div></section>
            <div class="case-overview-grid"><section class="panel"><div class="panel-heading"><h2>承办团队</h2><button class="text-button" @click="openAllocations()">管理分配<ArrowRight :size="14"/></button></div><div class="team-list"><div v-for="r in (caseLists.allocations||[]).filter(x=>x.scope_id===selectedCase.id)" :key="r.id" class="team-member"><span class="avatar">{{ lawyerName(r.lawyer_id).slice(-2) }}</span><div><strong>{{ lawyerName(r.lawyer_id) }}</strong><small>{{ r.role }}</small></div><span class="ratio-badge">{{ Number(r.ratio) }}%</span></div><div v-if="!(caseLists.allocations||[]).some(x=>x.scope_id===selectedCase.id)" class="compact-empty"><Users :size="26"/><p>尚未设置律师分配方案</p><button class="text-button" @click="openAllocations()">设置分配比例</button></div></div></section><section class="panel"><div class="panel-heading"><h2>案件日程</h2><button class="text-button" @click="openForm('tasks')"><Plus :size="15"/>添加事项</button></div><div class="schedule-list"><button v-for="task in (caseLists.tasks||[]).slice(0,3)" :key="task.id" class="schedule-item" @click="openRecord(task)"><div class="date-block"><strong>{{ task.due_on?.slice(8,10) }}</strong><small>{{ task.due_on?.slice(5,7) }}月</small></div><div><strong>{{ task.title }}</strong><small>{{ task.type }} · {{ lawyerName(task.assignee_id) }}</small></div><StatusBadge :status="task.status" :label="stateLabel('tasks',task.status)"/></button><div v-if="!caseLists.tasks?.length" class="compact-empty"><CalendarDays :size="28"/><p>暂无案件日程</p></div></div></section></div>
          </template>
          <template v-else-if="caseTab==='intake'">
            <section class="panel flow-panel"><div class="panel-heading"><div><h2>立案流程</h2><p>利冲审批通过后填写申请单，立案审批通过后开展合同与财务业务。</p></div></div><div class="stepper intake-stepper"><div v-for="(step,i) in ['利冲创建','利冲审批','立案申请单','立案审批']" :key="step" class="flow-step" :class="{done:intakeStage>i,current:intakeStage===i}"><span><Check v-if="intakeStage>i" :size="15"/><template v-else>{{ i+1 }}</template></span><strong>{{ step }}</strong><i v-if="i<3"></i></div></div></section>
            <div class="intake-cards"><section class="panel"><div class="panel-heading"><h2><ShieldCheck :size="19"/>利益冲突审查</h2><button class="btn small" @click="openForm('conflicts')"><Search :size="15"/>{{ latestConflict?'重新检索':'创建利冲' }}</button></div><div class="panel-body"><template v-if="latestConflict"><div class="review-summary" :class="latestConflict.matches?.length?'warning':'success'"><AlertCircle v-if="latestConflict.matches?.length" :size="24"/><ShieldCheck v-else :size="24"/><div><strong>{{ latestConflict.source_key?'历史利冲审查（详见原始明细）':latestConflict.matches?.length?`发现 ${latestConflict.matches.length} 项潜在冲突`:'未发现匹配主体' }}</strong><p>{{ latestConflict.source_key?'结果来自原系统历史快照，保留原审批记录。':'结果基于当前案件及当事人库，需由合伙人审查确认。' }}</p></div></div><div class="key-value"><span>审批状态</span><StatusBadge :status="latestConflict.status" :label="stateLabel('conflicts',latestConflict.status)"/></div><div v-if="!latestConflict.source_key && latestConflict.fingerprint!==selectedCase.conflict_fingerprint" class="error-banner">当事人信息已变更，需重新检索审批。</div><p class="muted">{{ latestConflict.review_note||'尚无审批意见' }}</p><div class="inline-actions"><button class="btn" @click="openRecord(latestConflict)">查看检索明细</button><button v-for="target in actions(latestConflict)" :key="target" class="btn" :class="target==='blocked'?'danger':'primary'" @click="openAction(latestConflict,target)">{{ actionNames[target] }}</button></div></template><div v-else class="empty-state compact"><ShieldCheck :size="35"/><h3>从利益冲突检索开始</h3><p>核查委托人、对方及关联方。</p></div></div></section><section class="panel"><div class="panel-heading"><h2><ClipboardCheck :size="19"/>立案申请单</h2><StatusBadge :status="selectedCase.status" :label="stateLabel('cases',selectedCase.status)"/></div><div class="panel-body"><div class="key-value"><span>案件名称</span><strong>{{ selectedCase.title }}</strong></div><div class="key-value"><span>主办律师</span><strong>{{ lawyerName(selectedCase.lead_lawyer_id) }}</strong></div><div class="key-value"><span>合同服务费</span><strong>{{ currency(selectedCase.amount,selectedCase.currency) }}</strong></div><div class="key-value"><span>业务类型</span><strong>{{ selectedCase.category }}</strong></div><div class="inline-actions"><button class="btn" @click="openForm('cases',selectedCase)" :disabled="!conflictApproved && intakeStage<4"><Pencil :size="15"/>填写申请单</button><button v-for="target in actions(selectedCase).filter((x:string)=>['draft','submitted','active','rejected'].includes(x))" :key="target" class="btn primary" @click="openAction(selectedCase,target)">{{ actionNames[target] }}</button></div><p v-if="intakeStage<2" class="hint"><LockKeyhole :size="14"/>利冲审批通过后进入立案申请阶段</p></div></section></div>
            <section class="panel"><div class="panel-heading"><h2>利冲申请记录</h2><span class="muted">完整保留每一次检索与审查</span></div><RecordTable :rows="caseLists.conflicts||[]" kind="conflicts" :states="states" :lawyers="lawyers" @open="openRecord"/><div v-if="caseTotals.conflicts>200" class="pagination"><span>共 {{ caseTotals.conflicts }} 条 · 第 {{ casePages.conflicts||1 }} 页</span><button class="btn small" :disabled="(casePages.conflicts||1)<=1" @click="casePages.conflicts=(casePages.conflicts||1)-1;loadCaseChildren()">上一页</button><button class="btn small" :disabled="(casePages.conflicts||1)*200>=caseTotals.conflicts" @click="casePages.conflicts=(casePages.conflicts||1)+1;loadCaseChildren()">下一页</button></div></section>
          </template>
          <template v-else-if="caseTab==='legacy'">
            <section class="panel"><div class="panel-heading"><h2>来源信息与变更历史</h2><button v-if="selectedCase.source_key && allowedAdmin" class="btn" @click="openLegacy(selectedCase)"><Database :size="16"/>历史关联明细</button><button class="btn" @click="showHistory(selectedCase)"><History :size="16"/>查看版本历史</button></div><div class="panel-body"><div class="notice"><Database :size="18"/>{{ selectedCase.source_key?'此案件来自 jw_db，完整源字段与源主键保留如下。':'此案件在新平台创建，没有源库记录。' }}</div><pre v-if="selectedCase.legacy_data" class="json-view">{{ JSON.stringify(selectedCase.legacy_data,null,2) }}</pre><div v-for="r in historyRows" :key="r.version" class="history-row"><strong>版本 {{ r.version }}</strong><span>{{ dateFull(r.created_at) }}</span><details><summary>查看字段快照</summary><pre>{{ JSON.stringify(r.data,null,2) }}</pre></details></div><div v-if="selectedCase.history?.length" class="timeline"><div v-for="(h,i) in selectedCase.history" :key="i"><i></i><strong>{{ h.actor }} · {{ stateLabel('cases',h.to) }}</strong><p>{{ h.note||'—' }}</p><small>{{ dateFull(h.at) }}</small></div></div></div></section>
          </template>
          <template v-else>
            <div v-if="caseTab==='finance'" class="stats-grid compact-stats"><div class="stat-card" v-for="[key,label] in [['contract','合同服务费'],['invoiced','已开票金额'],['received','已确认到账'],['outstanding','待收款金额']]" :key="key"><span>{{ label }}</span><strong>{{ currency(selectedCase.finance[key],selectedCase.currency) }}</strong></div></div>
            <div v-if="caseTab==='contracts'" class="process-notice"><FileCheck2 :size="22"/><div><strong>合同盖章 <ArrowRight :size="14"/> 合同归档</strong><p>上传合同原件 → 发起用印审批 → 上传已盖章文件 → 登记归档信息。用印明细同步在「案件用印」中。</p></div></div>
            <div v-if="caseTab==='finance' && selectedCase.finance.unresolved" class="notice"><AlertCircle :size="18"/>{{ selectedCase.finance.unresolved }} 条历史财务记录的金额或状态待核对，未计入生效金额。</div><div v-if="caseTab==='finance' && Object.keys(selectedCase.finance.other_currencies||{}).length" class="notice"><span v-for="(values,unit) in selectedCase.finance.other_currencies" :key="unit">{{ unit }}：到账 {{ currency((values as any).received,String(unit)) }}；开票 {{ currency((values as any).invoiced,String(unit)) }}</span></div><div v-if="caseTab==='finance'" class="process-notice"><CircleDollarSign :size="22"/><div><strong>开票申请 <ArrowRight :size="14"/> 开票审批 <ArrowRight :size="14"/> 到账信息</strong><p>已开票和到账确认时生成独立律师分配快照，各币种单独核算。</p></div></div>
            <section class="panel"><div v-if="caseTab==='finance'" class="sub-tabs"><button v-for="[key,label] in [['invoices','开票信息'],['receipts','到账信息'],['payment_plans','收款计划'],['allocations','律师分配']]" :key="key" :class="{active:financeTab===key}" @click="financeTab=key">{{ label }}</button></div><div class="panel-heading"><div><h2>{{ visibleCaseKind==='allocations'?'律师分配方案':schemas[visibleCaseKind]?.label+'明细' }}</h2><p>共 {{ caseTotals[visibleCaseKind]||0 }} 条记录</p></div><div class="inline-actions"><button v-if="visibleCaseKind!=='allocations'" class="btn" @click="exportRecords(visibleCaseKind)"><ArrowDownToLine :size="15"/>导出</button><button v-if="canWrite(visibleCaseKind)" class="btn primary" @click="visibleCaseKind==='allocations'?openAllocations():openForm(visibleCaseKind)"><Plus :size="16"/>{{ visibleCaseKind==='allocations'?'设置分配':visibleCaseKind==='documents'?'上传文档':'新增'+(schemas[visibleCaseKind]?.label||'记录') }}</button></div></div>
              <template v-if="visibleCaseKind==='allocations'"><div class="notice margin-notice"><Users :size="17"/>案件方案作为默认分配；发票与到账可在各自详情中设置独立方案。合计须为 100%。</div><div class="table-wrap"><table><thead><tr><th>律师</th><th>角色</th><th>比例</th><th>分配金额（保存时）</th><th>适用对象</th></tr></thead><tbody><tr v-for="r in caseLists.allocations||[]" :key="r.id"><td>{{ lawyerName(r.lawyer_id) }}</td><td>{{ r.role }}</td><td>{{ Number(r.ratio) }}%</td><td>{{ currency(r.amount,selectedCase.currency) }}</td><td>{{ r.scope_id===selectedCase.id?'案件默认分配':caseLists.invoices?.some(i=>i.id===r.scope_id)?'发票独立分配':'到账独立分配' }}</td></tr></tbody></table></div></template>
              <RecordTable v-else :rows="caseLists[visibleCaseKind]||[]" :kind="visibleCaseKind" :states="states" :lawyers="lawyers" :loading="loading" @open="openRecord"/>
              <div v-if="caseTotals[visibleCaseKind]>200" class="pagination"><span>共 {{ caseTotals[visibleCaseKind] }} 条，每页 200 条</span><button class="btn small" :disabled="(casePages[visibleCaseKind]||1)<=1" @click="casePages[visibleCaseKind]=(casePages[visibleCaseKind]||1)-1;loadCaseChildren()">上一页</button><span>{{ casePages[visibleCaseKind]||1 }}</span><button class="btn small" :disabled="(casePages[visibleCaseKind]||1)*200>=caseTotals[visibleCaseKind]" @click="casePages[visibleCaseKind]=(casePages[visibleCaseKind]||1)+1;loadCaseChildren()">下一页</button></div>
            </section>
          </template>
        </template>

        <template v-else-if="page==='admin'">
          <div class="page-heading"><div><span class="eyebrow">ADMINISTRATION</span><h1>管理后台</h1><p>人员权限、律所配置与历史数据管理</p></div><span class="admin-indicator"><ShieldCheck :size="16"/>{{ roles[user.role] }}</span></div>
          <div class="detail-tabs"><button v-if="user.role==='admin'" :class="{active:adminTab==='users'}" @click="adminTab='users'">账号与权限</button><button v-if="user.role==='admin'" :class="{active:adminTab==='departments'}" @click="adminTab='departments'">部门与成员</button><button v-if="user.role==='admin'" :class="{active:adminTab==='metadata'}" @click="adminTab='metadata'">元数据管理</button><button v-if="user.role==='admin'" :class="{active:adminTab==='api_keys'}" @click="adminTab='api_keys'">API Key 管理</button><button v-if="user.role==='admin'" :class="{active:adminTab==='settings'}" @click="adminTab='settings'">律所设置</button><button :class="{active:adminTab==='audit'}" @click="adminTab='audit'">操作审计</button><button v-if="user.role==='admin'" :class="{active:adminTab==='migration'}" @click="adminTab='migration'">数据迁移中心</button></div>
          <AdminDepartments v-if="adminTab==='departments' && user.role==='admin'" @changed="refreshManagedReferences"/>
          <AdminMetadata v-if="adminTab==='metadata' && user.role==='admin'" @changed="refreshManagedReferences"/>
          <AdminApiKeys v-if="adminTab==='api_keys' && user.role==='admin'"/>
          <PasswordResetAdmin v-if="adminTab==='users' && user.role==='admin'" :users="adminUsers" :people="adminPeople" :branches="schemas.lawyers?.branches||[]" :departments="schemas.lawyers?.fields?.find((f:any)=>f.key==='department')?.suggestions||[]"/><section v-if="adminTab==='users' && user.role==='admin'" class="panel"><div class="panel-heading"><div><h2>账号与权限</h2><p>管理员、合伙人、律师、财务与行政，按职责分配访问权限</p></div><button class="btn primary" @click="openUser()"><Plus :size="16"/>新增账号</button></div><div class="table-wrap"><table><thead><tr><th>成员</th><th>登录账号</th><th>角色</th><th>关联律师</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="u in adminUsers" :key="u.id"><td><span class="person"><span class="avatar tiny">{{ u.name.slice(-2) }}</span>{{ u.name }}</span></td><td>{{ u.username }}<small v-if="u.needs_password_reset">待首次设置密码</small><small v-if="u.migration_issue">{{ u.migration_issue }}</small></td><td>{{ roles[u.role] }}</td><td>{{ u.lawyer_id?lawyerName(u.lawyer_id):'—' }}</td><td><StatusBadge :status="u.active?'active':'void'" :label="u.active?'正常':'已禁用'"/></td><td><button class="text-button" @click="openUser(u)">编辑</button></td></tr></tbody></table></div><div class="permission-cards"><div v-for="[r,desc] in [['admin','系统配置、账号管理及全量业务'],['partner','案件统筹、利冲和立案审批'],['lawyer','本人主办或参与案件的办理'],['finance','非保密案件的财务处理及开票核销'],['clerk','非保密案件的用印、材料和归档']]" :key="r"><ShieldCheck :size="17"/><strong>{{ roles[r] }}</strong><p>{{ desc }}</p></div></div></section>
          <section v-if="adminTab==='settings' && user.role==='admin'" class="panel"><div class="panel-heading"><h2>律所基本设置</h2></div><form class="panel-body settings-form" @submit.prevent="saveSettings"><label class="form-field"><span>律所名称</span><input v-model="settings.firm.name" required></label><label class="form-field"><span>品牌说明</span><input v-model="settings.firm.subtitle"></label><button class="btn primary" :disabled="busy">保存设置</button></form></section>
          <section v-if="adminTab==='audit' || user.role==='partner'" class="panel"><div class="panel-heading"><h2>操作审计</h2><span class="muted">审批、财务、文档和权限变更均留痕</span></div><div class="table-wrap"><table><thead><tr><th>操作人</th><th>操作</th><th>模块</th><th>详情</th><th>时间</th></tr></thead><tbody><tr v-for="a in auditRows" :key="a.id"><td>{{ a.actor_name }}</td><td>{{ a.action }}</td><td>{{ schemas[a.kind]?.label||a.kind }}</td><td class="cell-text">{{ a.detail||'—' }}</td><td>{{ dateFull(a.created_at) }}</td></tr></tbody></table></div><div class="pagination"><span>共 {{ auditTotal }} 条</span><button class="btn small" :disabled="auditPage<=1" @click="auditPage--;loadAdmin()">上一页</button><span>{{ auditPage }}</span><button class="btn small" :disabled="auditPage*50>=auditTotal" @click="auditPage++;loadAdmin()">下一页</button></div></section>
          <template v-if="adminTab==='migration'"><div class="migration-hero"><span class="icon-tile lavender"><Database :size="27"/></span><div><h2>jw_db 历史数据迁移</h2><p>完整源表留存 + 业务字段映射 + 数量、金额与校验和核对</p></div><StatusBadge status="active" label="源结构已核对"/></div><div class="stats-grid compact-stats"><div class="stat-card"><span>核心及关联源表</span><strong>{{ migrationPlan?.tables?.length||0 }}<small>张</small></strong></div><div class="stat-card"><span>已导入源表</span><strong>{{ migration.tables.length }}<small>张</small></strong></div><div class="stat-card"><span>迁移批次</span><strong>{{ migration.runs.length }}<small>次</small></strong></div><div class="stat-card"><span>迁移状态</span><strong class="migration-state">{{ migration.runs[0]?.status||'尚未执行' }}</strong></div></div><div class="notice"><AlertCircle :size="20"/><span>源库只读。完整迁移通过服务器命令执行；文件实体需单独接入原文件存储。未确认的状态与关联进入异常清单，不作为迁移验收通过。</span></div><section class="panel"><div class="panel-heading"><h2>核心模块迁移范围</h2><span class="muted">结构核对时间：2026-11-12</span></div><div class="table-wrap"><table><thead><tr><th>模块</th><th>源表</th><th>字段数</th><th>记录量（估算）</th><th>迁移状态</th></tr></thead><tbody><tr v-for="t in migrationPlan?.tables||[]" :key="t.name"><td>{{ t.module }}</td><td><code>{{ t.name }}</code></td><td>{{ t.columns?.length||0 }}</td><td>{{ Number(t.estimated_rows||0).toLocaleString() }}</td><td><button v-if="migration.tables.some((x:any)=>x.name===t.name)" class="text-button" @click="legacyRecordId='';openSource(t.name)">查看完整源记录<ArrowUpRight :size="14"/></button><span v-else class="muted">待迁移</span></td></tr></tbody></table></div></section><section v-if="migration.supplemental_tables?.length" class="panel"><div class="panel-heading"><h2>补充字典与账号源表</h2></div><div class="panel-body"><div v-for="t in migration.supplemental_tables" :key="t.name" class="key-value"><span>{{ t.name }} · {{ t.row_count }} 条</span><button class="text-button" @click="legacyRecordId='';openSource(t.name)">查看源记录</button></div><p class="muted">账号源表不迁入旧密码；补充快照独立记录采集时间和校验和。</p></div></section><section class="panel"><div class="panel-heading"><h2>迁移批次与核对报告</h2></div><div class="panel-body"><div v-if="!migration.runs.length" class="compact-empty"><Database :size="30"/><p>尚未执行迁移。不会将演示数据计入迁移结果。</p></div><details v-for="r in migration.runs" :key="r.id" class="migration-report"><summary>{{ dateFull(r.created_at) }} · {{ r.status }} · {{ r.id }}</summary><pre class="json-view">{{ JSON.stringify(r.report,null,2) }}</pre></details></div></section><section class="panel"><div class="panel-heading"><h2>逐条迁移异常</h2><span class="muted">未解决 {{ migrationIssues.total }} 项</span></div><div v-if="migrationIssues.items.length" class="table-wrap"><table><thead><tr><th>源表</th><th>原始主键</th><th>问题类型</th><th>核对说明</th></tr></thead><tbody><tr v-for="issue in migrationIssues.items" :key="issue.id"><td>{{ issue.table_name }}</td><td><code>{{ issue.source_key }}</code></td><td>{{ issue.code }}</td><td>{{ issue.detail }}</td></tr></tbody></table></div><div v-else class="compact-empty"><ClipboardCheck :size="28"/><p>{{ migration.runs.length?'暂无未解决问题，请结合批次报告核对验收结果。':'执行迁移后显示逐条核对问题。' }}</p></div><div v-if="migrationIssues.total>50" class="pagination"><span>第 {{ issuePage }} 页</span><button class="btn small" :disabled="issuePage<=1" @click="issuePage--;loadAdmin()">上一页</button><button class="btn small" :disabled="issuePage*50>=migrationIssues.total" @click="issuePage++;loadAdmin()">下一页</button></div></section></template>
        </template>

        <template v-else>
          <div class="page-heading"><div><span class="eyebrow">{{ page.toUpperCase() }} MANAGEMENT</span><h1>{{ currentTitle }}</h1><p>{{ pageSubtitle[page] }}</p></div><div class="heading-actions"><button class="btn" @click="exportRecords()"><ArrowDownToLine :size="16"/>导出数据</button><button v-if="canWrite(currentKind)" class="btn primary" @click="openForm(currentKind)"><Plus :size="18"/>{{ page==='cases'||page==='conflicts'?'发起立案':page==='documents'?'上传文档':'新增'+(schemas[currentKind]?.label||'记录') }}</button></div></div>
          <div v-if="page==='cases'" class="case-list-intro"><div class="icon-tile lavender"><BriefcaseBusiness :size="24"/></div><div><strong>每一份委托，始于审慎，成于专业。</strong><p>利冲创建 → 利冲审批 → 立案申请单 → 立案审批</p></div><button class="text-button" @click="openIntake">开启新的案件<ArrowRight :size="15"/></button></div>
          <LawyerTeam v-if="page==='lawyers'" :members="lawyers" :departments="schemas.lawyers?.fields.find((f:any)=>f.key==='department')?.suggestions||[]" :branches="schemas.lawyers?.branches||[]" :states="states.lawyers||{}" @open="openRecord"/>
          <section v-else class="panel"><div v-if="page==='finance'" class="sub-tabs"><button v-for="[key,label] in [['invoices','开票信息'],['receipts','到账信息'],['payment_plans','收款计划']]" :key="key" :class="{active:financeTab===key}" @click="financeTab=key">{{ label }}</button></div><div class="table-toolbar"><div class="search-box"><Search :size="17"/><input v-model="search" :placeholder="page==='cases'?'搜索案件名称、编号、客户…':'搜索名称、编号、关联信息…'" aria-label="搜索记录"/><button v-if="search" @click="search=''" class="icon-button"><X :size="14"/></button></div><div class="toolbar-right"><div v-if="page==='cases'" class="filter-control"><Building2 :size="16"/><select v-model="caseBranch" aria-label="筛选分支机构"><option value="">全部分支机构</option><option value="CS">长沙（CS）</option><option value="HZ">杭州（HZ）</option></select></div><div class="filter-control"><ListFilter :size="16"/><select v-model="filterStatus" aria-label="筛选状态"><option value="">全部状态</option><option v-for="(label,key) in states[currentKind]" :key="key" :value="key">{{ label }}</option></select></div><span class="result-count">共 <strong>{{ total }}</strong> 条记录</span></div></div><RecordTable :rows="records" :kind="currentKind" :states="states" :lawyers="lawyers" :loading="loading" @open="openRecord"/><div class="pagination"><span>显示 {{ total?(listPage-1)*pageSize+1:0 }}–{{ Math.min(listPage*pageSize,total) }} 条，共 {{ total }} 条</span><div><button :disabled="listPage<=1" class="page-arrow" @click="listPage--" aria-label="上一页"><ChevronLeft :size="16"/></button><span class="page-number">{{ listPage }}</span><button :disabled="listPage*pageSize>=total" class="page-arrow" @click="listPage++" aria-label="下一页"><ChevronRight :size="16"/></button></div></div></section>
        </template>
        <footer class="content-footer"><span>律序 · 让专业更有序</span><span><ShieldCheck :size="13"/>数据有权限，操作有记录</span></footer>
      </main>
    </div>
  </div>

  <div v-if="inspector" class="drawer-backdrop" @click.self="inspector=null"><aside class="detail-drawer"><div class="drawer-header"><div><span class="eyebrow">{{ schemas[inspector.kind]?.label }}详情</span><h2>{{ inspector.title||inspector.name }}</h2></div><button class="icon-button" @click="inspector=null" aria-label="关闭详情"><X :size="22"/></button></div><div class="drawer-content"><div class="drawer-status"><StatusBadge :status="inspector.status" :label="stateLabel(inspector.kind,inspector.status)"/><span class="muted">版本 {{ inspector.version }}</span></div><div class="inline-actions"><button v-if="canEdit(inspector)" class="btn small" @click="openForm(inspector.kind,inspector)"><Pencil :size="14"/>编辑</button><button v-if="['invoices','receipts'].includes(inspector.kind)" class="btn small" @click="openAllocations(inspector)"><Users :size="14"/>独立分配</button><button v-if="inspector.kind==='documents'" class="btn small" @click="openUpload(inspector)"><Upload :size="14"/>新版本</button><button v-if="inspector.case_id" class="btn small" @click="navigateCase(inspector.case_id);inspector=null"><BriefcaseBusiness :size="14"/>进入案件</button></div><div class="detail-fields"><div v-for="f in schemas[inspector.kind]?.fields||[]" :key="f.key" :class="{wide:f.type==='textarea'}"><label>{{ f.label }}</label><p>{{ displayValue(f,inspector) }}</p></div></div><template v-if="inspector.kind==='conflicts'"><div class="section-label">检索命中记录</div><HistoricalSnapshot v-if="inspector.source_key" :record="inspector"/><p v-else-if="!inspector.matches?.length" class="notice">{{ inspector.source_key?'历史检索原文可在源字段中查看。':'未发现匹配；请根据实际业务关系复核。' }}</p><p v-if="inspector.truncated" class="error-banner">命中过多，当前显示前 500 条；请缩小范围进一步核对。</p><div v-for="(match,i) in inspector.matches||[]" :key="i" class="conflict-match"><span class="icon-tile amber small"><AlertCircle :size="17"/></span><div><strong>{{ match.name }}</strong><p>{{ match.relation }} · {{ match.case_title||'历史关联案件' }}</p><small>{{ match.case_number }}</small></div><button v-if="match.case_id" class="text-button" @click="navigateCase(match.case_id);inspector=null">查看</button></div></template><template v-if="inspector.kind==='documents'"><div class="section-label">文件版本</div><div v-for="(file,i) in inspector.files||[]" :key="file.blob" class="file-version"><FileText :size="23"/><div><strong>{{ file.filename }}</strong><small>v{{ Number(i)+1 }} · {{ (file.size/1024).toFixed(1) }} KB · {{ dateFull(file.uploaded_at) }}</small><code :title="file.sha256">SHA256 {{ file.sha256?.slice(0,16) }}…</code></div><button class="icon-button" @click="downloadFile(inspector,Number(i))" aria-label="下载文件"><ArrowDownToLine :size="18"/></button></div><div v-if="!inspector.files?.length" class="notice">当前只有历史路径引用，尚未迁移实体文件。</div></template><template v-if="inspector.allocation_snapshot"><div class="section-label">已确认分配快照</div><div v-for="(r,i) in inspector.allocation_snapshot" :key="i" class="key-value"><span>{{ lawyerName(r.lawyer_id) }} · {{ r.ratio }}%</span><strong>{{ currency(r.amount) }}</strong></div></template><div class="section-label">流程记录</div><div class="timeline"><div v-for="(h,i) in inspector.history||[]" :key="i"><i></i><strong>{{ h.actor }} · {{ stateLabel(inspector.kind,h.to) }}</strong><p>{{ h.note||'—' }}</p><small>{{ dateFull(h.at) }}</small></div><p v-if="!inspector.history?.length" class="muted">暂无流转记录</p></div><button v-if="inspector.source_key && ['conflicts','documents'].includes(inspector.kind)" class="btn small" @click="openLegacy(inspector)"><Database :size="15"/>查看完整历史明细</button><details v-if="inspector.legacy_data" class="legacy-details"><summary>完整源数据与原始字段</summary><pre class="json-view">{{ JSON.stringify(inspector.legacy_data,null,2) }}</pre></details><button class="text-button" @click="showHistory(inspector)"><History :size="15"/>查看全部修改版本</button><div v-for="v in historyRows" :key="v.version" class="history-row"><details><summary>版本 {{ v.version }} · {{ dateFull(v.created_at) }}</summary><pre>{{ JSON.stringify(v.data,null,2) }}</pre></details></div><button v-if="canDelete(inspector)" class="text-button danger-text delete-link" @click="startDelete(inspector)"><Trash2 :size="14"/>删除未生效记录</button></div><div class="drawer-footer"><button v-for="target in actions(inspector)" :key="target" class="btn" :class="['blocked','rejected','void'].includes(target)?'danger':'primary'" @click="openAction(inspector,target)">{{ actionNames[target]||stateLabel(inspector.kind,target) }}</button><p v-if="!actions(inspector).length" class="muted">当前状态暂无可执行的下一步</p></div></aside></div>

  <div v-if="modal" class="modal-backdrop" @click.self="!busy && (modal='')"><section class="modal" :class="{large:['form','intake','source','allocations'].includes(modal)}" role="dialog" aria-modal="true"><header><div><span class="eyebrow">{{ modal==='intake'?'NEW CASE INTAKE':'LAW OFFICE WORKSPACE' }}</span><h2>{{ ['form','intake'].includes(modal)?modalTitle:({action:actionNames[actionTarget]||'更新流程',conflict:'发起利益冲突审查',allocations:'设置律师分配',upload:'上传案件文档',user:userEditId?'编辑账号':'新增账号',delete:'删除记录',profile:'个人账号',password:'修改密码',source:`源表 · ${sourceTable}`} as any)[modal] }}</h2></div><button class="icon-button" :disabled="busy" @click="modal=''" aria-label="关闭弹窗"><X :size="22"/></button></header>
    <form v-if="['form','intake'].includes(modal)" @submit.prevent="saveForm"><div class="modal-body"><div v-if="modal==='intake'" class="notice"><ShieldCheck :size="20"/>先填写委托人和对方信息并创建利冲；审批通过后完善立案申请单。</div><label v-if="modal==='form' && !selectedCase && !['cases','lawyers'].includes(modalKind)" class="form-field mb"><span>搜索案件</span><input placeholder="输入案号、客户或案件名称查找更多案件" @input="searchCaseChoices"></label><label v-if="modal==='form' && !selectedCase && !['cases','lawyers'].includes(modalKind)" class="form-field mb"><span>所属案件 *</span><select v-model="formCase" required @change="loadFormReferences(formCase)"><option value="">请选择案件</option><option v-for="c in formCaseChoices" :key="c.id" :value="c.id">{{ c.number }} · {{ c.title }}</option></select></label><SchemaForm :fields="formFields" :model="form" :lawyers="lawyers" :branches="schemas.lawyers?.branches||[]" :departments="schemas.lawyers?.fields?.find((f:any)=>f.key==='department')?.suggestions||[]" :references="references"/><p v-if="modalKind==='seals'||modalKind==='contracts'" class="hint">先在案件文档中上传文件，再选择需要用印 / 归档的版本。</p></div><footer><button type="button" class="btn" @click="modal=''">取消</button><button class="btn primary" :disabled="busy"><LoaderCircle v-if="busy" :size="16" class="spin"/>{{ modal==='intake'?'创建并提交利冲审批':'保存信息' }}</button></footer></form>
    <form v-else-if="modal==='action'" @submit.prevent="confirmAction"><div class="modal-body"><div class="action-flow"><StatusBadge :status="actionRecord.status" :label="stateLabel(actionRecord.kind,actionRecord.status)"/><ArrowRight :size="20"/><StatusBadge :status="actionTarget" :label="stateLabel(actionRecord.kind,actionTarget)"/></div><p>{{ actionRecord.title||actionRecord.name }}</p><label class="form-field"><span>审批意见 / 操作说明 *</span><textarea v-model="actionNote" required rows="4" placeholder="请填写审查结论、处理意见或操作依据"></textarea></label><p class="hint">操作人：{{ user.name }} · 此操作将记录在流程历史中。</p></div><footer><button type="button" class="btn" @click="modal=''">取消</button><button class="btn primary" :disabled="busy">确认{{ actionNames[actionTarget]||'操作' }}</button></footer></form>
    <form v-else-if="modal==='conflict'" @submit.prevent="submitConflict"><div class="modal-body"><div class="notice"><Search :size="19"/>自动检索委托人、对方与已登记当事人，同时保留本次结果快照。</div><label class="form-field"><span>补充检索主体（多个以分号分隔）</span><input v-model="conflictForm.query" placeholder="关联公司、曾用名或其他相关方"></label><label class="form-field mt"><span>申请说明</span><textarea v-model="conflictForm.notes" rows="3"></textarea></label></div><footer><button class="btn" type="button" @click="modal=''">取消</button><button class="btn primary" :disabled="busy">检索并发起审批</button></footer></form>
    <form v-else-if="modal==='allocations'" @submit.prevent="saveAllocations"><div class="modal-body"><div class="notice"><CircleDollarSign :size="20"/>{{ allocationScope.title }} · 分配基数 {{ currency(allocationScope.amount,selectedCase?.currency) }}</div><div class="allocation-editor" v-for="(row,i) in allocationRows" :key="i"><PersonPicker v-model="row.lawyer_id" :people="lawyers" :branches="schemas.lawyers?.branches||[]" :departments="schemas.lawyers?.fields?.find((f:any)=>f.key==='department')?.suggestions||[]" label="律师" required active-only /><label class="form-field"><span>承办角色</span><input v-model="row.role" required></label><label class="form-field"><span>分配比例 %</span><input v-model="row.ratio" type="number" min="0.0001" max="100" step="0.0001" required></label><button type="button" class="icon-button" @click="allocationRows.splice(i,1)" aria-label="移除此律师"><X :size="17"/></button></div><button type="button" class="text-button" @click="allocationRows.push({lawyer_id:'',ratio:'',role:'协办律师'})"><Plus :size="16"/>添加律师</button><div class="allocation-total" :class="Math.abs(allocationTotal-100)<.00001?'text-green':'text-amber'">合计 <strong>{{ allocationTotal.toFixed(4).replace(/\.?0+$/,'') }}%</strong><span>须等于 100%</span></div></div><footer><button type="button" class="btn" @click="modal=''">取消</button><button class="btn primary" :disabled="busy">保存分配方案</button></footer></form>
    <form v-else-if="modal==='upload'" @submit.prevent="doUpload"><div class="modal-body"><label v-if="!selectedCase" class="form-field mb"><span>搜索案件</span><input placeholder="输入案号或案件名称" @input="searchCaseChoices"></label><label v-if="!selectedCase" class="form-field mb"><span>所属案件 *</span><select v-model="uploadForm.case_id" required><option value="">请选择案件</option><option v-for="c in formCaseChoices" :key="c.id" :value="c.id">{{ c.number }} · {{ c.title }}</option></select></label><div class="form-grid"><label class="form-field"><span>文档名称</span><input v-model="uploadForm.title" placeholder="留空使用文件名"></label><label class="form-field"><span>文档分类</span><select v-model="uploadForm.category"><option v-for="c in schemas.documents.fields.find((f:any)=>f.key==='category').options" :key="c">{{ c }}</option></select></label></div><label class="upload-zone"><Upload :size="34"/><strong>{{ uploadFile?.name||'点击选择需要上传的文件' }}</strong><span>单文件不超过 50MB · 自动保存 SHA-256 校验值</span><input type="file" @change="filePicked" required></label></div><footer><button type="button" class="btn" @click="modal=''">取消</button><button class="btn primary" :disabled="busy"><Upload :size="16"/>上传并保存</button></footer></form>
    <form v-else-if="modal==='user'" @submit.prevent="saveUser"><div class="modal-body form-grid"><label class="form-field"><span>登录账号 *</span><input v-model="userForm.username" :disabled="!!userEditId" required></label><label class="form-field"><span>姓名 *</span><input v-model="userForm.name" required></label><label class="form-field"><span>角色 *</span><select v-model="userForm.role"><option v-for="(label,key) in roles" :key="key" :value="key">{{ label }}</option></select></label><PersonPicker v-model="userForm.lawyer_id" :people="lawyers" :branches="schemas.lawyers?.branches||[]" :departments="schemas.lawyers?.fields?.find((f:any)=>f.key==='department')?.suggestions||[]" label="关联律师档案" :required="userForm.role==='lawyer'" active-only /><label class="form-field wide"><span>{{ userEditId?'重置密码（留空不变）':'初始密码 *' }}</span><input v-model="userForm.password" type="password" minlength="12" :required="!userEditId" autocomplete="new-password" placeholder="至少 12 位"></label><label v-if="userEditId" class="inline-check"><input type="checkbox" v-model="userForm.active">账号启用</label></div><footer><button type="button" class="btn" @click="modal=''">取消</button><button class="btn primary" :disabled="busy">保存账号</button></footer></form>
    <template v-else-if="modal==='delete'"><div class="modal-body"><p>确认删除「{{ actionRecord.title||actionRecord.name }}」？</p><p class="muted">仅允许移除未生效且未被引用的记录，审计与历史版本会保留。</p></div><footer><button class="btn" @click="modal=''">取消</button><button class="btn danger" :disabled="busy" @click="confirmDelete">确认删除</button></footer></template>
    <template v-else-if="modal==='profile'"><div class="modal-body profile-summary"><span class="avatar large">{{ user.name.slice(-2) }}</span><h2>{{ user.name }}</h2><p>{{ roles[user.role] }} · {{ user.username }}</p><button class="btn full" @click="modal='password'"><LockKeyhole :size="16"/>修改密码</button><button class="btn full" @click="modal='';signOut()"><LogOut :size="16"/>退出登录</button></div></template>
    <form v-else-if="modal==='password'" @submit.prevent="changePassword"><div class="modal-body"><label class="form-field"><span>原密码</span><input type="password" v-model="passwordForm.old_password" required autocomplete="current-password"></label><label class="form-field mt"><span>新密码（至少 12 位）</span><input type="password" v-model="passwordForm.password" required minlength="12" autocomplete="new-password"></label></div><footer><button class="btn primary" :disabled="busy">更新密码</button></footer></form>
    <template v-else-if="modal==='source'"><div class="modal-body"><label v-if="legacyRecordId" class="form-field mb"><span>关联源表</span><select v-model="sourceTable" @change="openSource(sourceTable)"><option v-for="t in legacyTables" :key="t">{{ t }}</option></select></label><div class="table-wrap"><table><thead><tr><th v-for="key in Object.keys(sourceRows[0]||{})" :key="key">{{ key }}</th></tr></thead><tbody><tr v-for="(row,i) in sourceRows" :key="i"><td v-for="(v,key) in row" :key="key" class="source-cell" :title="String(v)">{{ v===null?'NULL':String(v) }}</td></tr></tbody></table></div></div><footer><span class="muted">共 {{ sourceTotal }} 条 · 第 {{ sourcePage }} 页</span><button class="btn" :disabled="sourcePage<=1" @click="openSource(sourceTable,sourcePage-1)">上一页</button><button class="btn" :disabled="sourcePage*20>=sourceTotal" @click="openSource(sourceTable,sourcePage+1)">下一页</button></footer></template>
  </section></div>
  <Transition name="toast"><div v-if="toast" class="toast" :class="{error:toast.error}" role="status"><AlertCircle v-if="toast.error" :size="19"/><CheckCircle2 v-else :size="19"/><span>{{ toast.message }}</span><button class="icon-button" @click="toast=null" aria-label="关闭提示"><X :size="16"/></button></div></Transition>
</template>
